<template>
<main class="signup-page"><header class="signup-top"><RouterLink to="/"><img src="/img/logo2.png" alt="카리나벨" /></RouterLink><RouterLink to="/login">로그인 <i class="fa-solid fa-arrow-right"></i></RouterLink></header><section class="signup-shell"><aside class="signup-intro"><p class="eyebrow">JOIN KARINABEL</p><h1>향기로운 일상의<br />첫걸음</h1><p>카리나벨 회원이 되어 특별한 회원 혜택과 엄선된 에센셜 오일을 만나보세요.</p><ol><li :class="{active:step===1,done:step>1}"><span>{{step>1?'✓':'01'}}</span><div><strong>기본 정보</strong><small>회원 정보와 약관 동의</small></div></li><li :class="{active:step===2}"><span>02</span><div><strong>배송 정보</strong><small>주소와 추천인 입력</small></div></li></ol></aside>
<div class="signup-form-card"><div class="signup-card-head"><span>STEP {{step}} / 2</span><h2>{{step===1?'회원 정보를 입력해 주세요.':'배송 정보를 입력해 주세요.'}}</h2><p>{{step===1?'모든 정보는 안전하게 보호됩니다.':'상품을 받아보실 주소를 알려주세요.'}}</p></div>
<form novalidate @submit.prevent="handleSubmit"><div v-if="step===1" class="signup-fields"><label><span>이름 *</span><input v-model.trim="fullName" type="text" autocomplete="name" placeholder="이름" /></label><label><span>이메일 *</span><input v-model.trim="email" type="email" autocomplete="email" placeholder="example@email.com" /></label><label><span>휴대폰 번호 *</span><input :value="formattedPhone" type="tel" inputmode="numeric" autocomplete="tel" placeholder="010-0000-0000" @input="formatPhoneInput" /></label><label><span>생년월일 *</span><input v-model="birthday" type="date" /></label><label><span>비밀번호 *</span><div class="signup-password"><input v-model="password" :type="showPassword?'text':'password'" autocomplete="new-password" placeholder="비밀번호 입력" /><button type="button" @click="showPassword=!showPassword"><i :class="showPassword?'fa-regular fa-eye-slash':'fa-regular fa-eye'"></i></button></div><small>안전한 비밀번호를 사용해 주세요.</small></label><label><span>비밀번호 확인 *</span><input v-model="confirmPassword" type="password" autocomplete="new-password" placeholder="비밀번호 다시 입력" /></label>
<div class="terms-box"><label><input v-model="agreedToTerms" type="checkbox" /><span><i class="fa-solid fa-check"></i></span><strong>이용약관 및 개인정보 처리방침에 동의합니다.</strong></label><div><a href="/file/카리나벨 이용약관.pdf" target="_blank">이용약관 보기</a><a href="/file/카리나벨 개인정보취급방침.pdf" target="_blank">개인정보 처리방침 보기</a></div></div></div>
<div v-else class="signup-fields step-two"><label><span>우편번호 *</span><div class="address-row"><input :value="zoneCode" readonly placeholder="주소 찾기를 이용해 주세요." /><button type="button" @click="searchAddress">주소 찾기</button></div></label><label><span>기본주소 *</span><input :value="baseAddress" readonly placeholder="기본주소" /></label><label><span>상세주소</span><input v-model.trim="detailAddress" type="text" autocomplete="street-address" placeholder="동·호수 등 상세주소" /></label><label><span>추천인 회원번호</span><input v-model.trim="referrermemberId" type="text" placeholder="추천인이 있는 경우 입력" /><small>추천인이 없는 경우 비워두셔도 됩니다.</small></label></div>
<p v-if="errorMessage" class="signup-error" role="alert"><i class="fa-solid fa-circle-exclamation"></i>{{errorMessage}}</p><div class="signup-actions"><button v-if="step===2" type="button" class="signup-back" @click="step=1"><i class="fa-solid fa-arrow-left"></i> 이전</button><button v-if="step===1" type="button" class="signup-next" @click="nextStep">다음 단계 <i class="fa-solid fa-arrow-right"></i></button><button v-else type="submit" class="signup-next" :disabled="isSubmitting"><span v-if="isSubmitting" class="auth-spinner"></span>{{isSubmitting?'가입 처리 중...':'회원가입 완료'}}</button></div></form></div></section></main>
</template>
<script setup>
import{computed,ref}from"vue";import{useRouter}from"vue-router";import AuthService from"@/api/AuthService";const router=useRouter();const step=ref(1),fullName=ref(""),phone=ref(""),birthday=ref(""),email=ref(""),password=ref(""),confirmPassword=ref(""),agreedToTerms=ref(false),baseAddress=ref(""),zoneCode=ref(""),detailAddress=ref(""),referrermemberId=ref(""),showPassword=ref(false),errorMessage=ref(""),isSubmitting=ref(false);const formattedPhone=computed(()=>{const r=phone.value;if(r.length<=3)return r;if(r.length<=7)return`${r.slice(0,3)}-${r.slice(3)}`;return`${r.slice(0,3)}-${r.slice(3,7)}-${r.slice(7,11)}`});const formatPhoneInput=e=>{phone.value=e.target.value.replace(/\D/g,"").slice(0,11);e.target.value=formattedPhone.value};const validateFirst=()=>{if(!fullName.value||!email.value||!phone.value||!birthday.value||!password.value||!confirmPassword.value)return"필수 항목을 모두 입력해 주세요.";if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value))return"올바른 이메일 주소를 입력해 주세요.";if(phone.value.length<10)return"휴대폰 번호를 확인해 주세요.";if(password.value.length<6)return"비밀번호는 6자 이상 입력해 주세요.";if(password.value!==confirmPassword.value)return"비밀번호가 서로 일치하지 않습니다.";if(!agreedToTerms.value)return"이용약관과 개인정보 처리방침에 동의해 주세요.";return""};const nextStep=()=>{errorMessage.value=validateFirst();if(!errorMessage.value){step.value=2;window.scrollTo({top:0,behavior:"smooth"})}};const searchAddress=()=>{if(!window.daum?.Postcode){errorMessage.value="주소 검색 서비스를 불러오지 못했습니다.";return}new window.daum.Postcode({oncomplete:data=>{let address=data.address;if(data.addressType==="R"){if(data.bname)address+=` (${data.bname})`;if(data.buildingName)address+=`, ${data.buildingName}`}baseAddress.value=address;zoneCode.value=data.zonecode;errorMessage.value=""}}).open()};const handleSubmit=async()=>{errorMessage.value="";if(!baseAddress.value){errorMessage.value="주소 찾기를 통해 배송 주소를 입력해 주세요.";return}isSubmitting.value=true;try{const response=await AuthService.register({fullName:fullName.value,email:email.value,phone:phone.value,birthday:birthday.value,password:password.value,address:`${zoneCode.value} ${baseAddress.value} ${detailAddress.value}`.trim(),referrermemberId:referrermemberId.value,agreedToTerms:agreedToTerms.value});alert(`회원가입이 완료되었습니다.\n회원번호: ${response.data.memberId}`);router.push("/login")}catch(error){console.error(error);errorMessage.value=error.response?.data?.message||"회원가입을 완료하지 못했습니다. 입력 정보를 확인해 주세요."}finally{isSubmitting.value=false}};
</script>
<style>
.signup-page{min-height:100vh;background:#f6f3f0}.signup-top{height:82px;display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,5vw);border-bottom:1px solid #e7dfdc;background:#fff}.signup-top img{width:145px;height:58px;object-fit:contain}.signup-top>a:last-child{color:#766b70;font-size:.7rem;font-weight:700;letter-spacing:.06em}.signup-top i{margin-left:8px}.signup-shell{width:min(calc(100% - 48px),1120px);display:grid;grid-template-columns:330px 1fr;gap:70px;margin:0 auto;padding:75px 0 110px}.signup-intro{padding-top:28px}.signup-intro h1{margin:15px 0 20px;font-family:Georgia,"Noto Serif KR",serif;font-size:3rem;font-weight:400;line-height:1.28}.signup-intro>p:not(.eyebrow){color:#80767b;font-size:.82rem;line-height:1.8}.signup-intro ol{margin-top:65px}.signup-intro li{display:flex;gap:17px;position:relative;padding-bottom:37px;color:#a69ca1}.signup-intro li:first-child:after{content:"";position:absolute;left:17px;top:36px;width:1px;height:30px;background:#dcd4d7}.signup-intro li>span{width:35px;height:35px;display:grid;place-items:center;border:1px solid #cec4c8;border-radius:50%;font-size:.65rem}.signup-intro li.active,.signup-intro li.done{color:var(--color-brand-dark)}.signup-intro li.active>span,.signup-intro li.done>span{border-color:var(--color-brand);color:#fff;background:var(--color-brand)}.signup-intro li strong,.signup-intro li small{display:block}.signup-intro li strong{font-size:.8rem}.signup-intro li small{margin-top:2px;font-size:.65rem}.signup-form-card{padding:45px 50px;background:#fff;box-shadow:0 18px 55px rgba(58,41,49,.07)}.signup-card-head{padding-bottom:27px;border-bottom:1px solid #ebe4e1}.signup-card-head>span{color:var(--color-accent);font-size:.63rem;font-weight:800;letter-spacing:.15em}.signup-card-head h2{margin:7px 0 4px;font-family:Georgia,"Noto Serif KR",serif;font-size:1.65rem;font-weight:400}.signup-card-head p{color:#9a9095;font-size:.7rem}.signup-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px 22px;padding-top:28px}.signup-fields>label>span{display:block;margin-bottom:7px;color:#5d5559;font-size:.7rem;font-weight:700}.signup-fields input{width:100%;height:48px;padding:0 14px;border:1px solid #ddd5d8;outline:0;background:#fff;font-size:.78rem}.signup-fields input:focus{border-color:var(--color-brand);box-shadow:0 0 0 3px rgba(134,101,119,.07)}.signup-fields input[readonly]{color:#7d7478;background:#f8f6f4}.signup-fields label>small{display:block;margin-top:6px;color:#aaa1a5;font-size:.6rem}.signup-password{display:flex;border:1px solid #ddd5d8}.signup-password:focus-within{border-color:var(--color-brand)}.signup-password input{border:0}.signup-password button{width:43px;border:0;background:#fff;color:#958b90}.terms-box{grid-column:1/-1;padding:18px;background:#f8f5f3}.terms-box>label{display:flex;align-items:center;gap:9px;color:#5c5458;font-size:.7rem;cursor:pointer}.terms-box input{position:absolute;opacity:0}.terms-box label>span{width:18px;height:18px;display:grid;place-items:center;border:1px solid #c9bec3}.terms-box label>span i{opacity:0;color:#fff;font-size:.55rem}.terms-box input:checked+span{border-color:var(--color-brand);background:var(--color-brand)}.terms-box input:checked+span i{opacity:1}.terms-box>div{display:flex;gap:16px;margin:10px 0 0 27px}.terms-box a{color:#897e83;font-size:.62rem;text-decoration:underline}.step-two{grid-template-columns:1fr}.address-row{display:grid;grid-template-columns:1fr 110px}.address-row button{border:0;color:#fff;background:var(--color-brand);font-size:.72rem}.signup-error{margin-top:20px;color:#ad5964;font-size:.7rem}.signup-error i{margin-right:6px}.signup-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:30px}.signup-actions button{height:50px;padding:0 28px;border:1px solid var(--color-brand);font-size:.76rem;font-weight:700}.signup-back{color:var(--color-brand);background:#fff}.signup-next{min-width:150px;display:flex;align-items:center;justify-content:center;gap:9px;color:#fff;background:var(--color-brand-dark)}.signup-next i{margin-left:10px}.signup-next:disabled{opacity:.6}@media(max-width:850px){.signup-shell{grid-template-columns:1fr;padding-top:40px}.signup-intro{padding-top:0;text-align:center}.signup-intro h1{font-size:2.5rem}.signup-intro ol{display:flex;justify-content:center;gap:30px;margin-top:30px}.signup-intro li:first-child:after{display:none}.signup-intro li{padding:0}.signup-form-card{padding:38px 35px}}@media(max-width:600px){.signup-shell{width:calc(100% - 24px);gap:35px}.signup-top{height:70px}.signup-top img{width:120px}.signup-form-card{padding:30px 20px}.signup-fields{grid-template-columns:1fr}.terms-box{grid-column:auto}.terms-box>div{flex-direction:column;gap:5px}.signup-actions button{flex:1;padding:0 12px}}
</style>
